package dev.veltraph.client.rewarp;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class RetainedCoordinatorOriginalDeadlineTest {
    @Test void exactOriginalBoundaryExpires(){var l=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),100,15000);assertTrue(l.deadlineCurrent(t,15099));assertFalse(l.deadlineCurrent(t,15100));assertEquals(FarmMaintenanceLease.State.PREPARED,l.state());}
    @Test void elapsedPreparedTimeIsNotResetByCommit(){var l=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),100,15000);assertTrue(l.commit(t));assertFalse(l.deadlineCurrent(t,15100));assertEquals(FarmMaintenanceLease.State.HELPER_ACTIVE,l.state());}
    @Test void freshOriginalFinalReadDetectsTimePassingWithinTick(){var l=new FarmMaintenanceLease();var farm=new Object();var helper=new Object();var t=l.prepare(farm,helper,100,15000);assertTrue(l.commit(t));assertTrue(l.validate(t,farm,helper,14999,true));assertTrue(l.deadlineCurrent(t,15000));assertFalse(l.deadlineCurrent(t,15100));}
    @Test void backwardsClockRefusesWithoutRefreshingLast(){var l=new FarmMaintenanceLease();var f=new Object();var h=new Object();var t=l.prepare(f,h,100,15000);l.commit(t);assertTrue(l.validate(t,f,h,1000,true));assertFalse(l.deadlineCurrent(t,999));assertTrue(l.deadlineCurrent(t,1000));}
    @Test void foreignTokenCannotReadCurrentLease(){var a=new FarmMaintenanceLease();var b=new FarmMaintenanceLease();var ta=a.prepare(new Object(),new Object(),100,15000);var tb=b.prepare(new Object(),new Object(),100,15000);assertFalse(a.deadlineCurrent(tb,101));assertTrue(a.deadlineCurrent(ta,101));}
    @Test void cancelledLeaseCannotReopenOnEarlierTime(){var l=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),100,15000);l.commit(t);l.cancel(t,"cancelled");assertFalse(l.deadlineCurrent(t,101));}
    @Test void restoredAndReturningStillUseOriginalDeadline(){var l=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),100,15000);l.commit(t);l.beginRestore(t);l.beginReturn(t);l.ready(t);assertTrue(l.deadlineCurrent(t,15099));assertFalse(l.deadlineCurrent(t,15100));}
    @Test void completedAndRolledBackLeaseAreNotCurrent(){var l=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),100,15000);l.commit(t);l.beginRestore(t);l.beginReturn(t);l.ready(t);l.resume(t);assertFalse(l.deadlineCurrent(t,101));l.clear();var other=l.prepare(new Object(),new Object(),200,15000);l.rollback(other);assertFalse(l.deadlineCurrent(other,201));}
    @Test void nullTokenAndBeforeStartRefuse(){var l=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),100,15000);assertFalse(l.deadlineCurrent(null,101));assertFalse(l.deadlineCurrent(t,99));}
    @Test void overflowCannotBecomeFreshElapsedTime(){var l=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),Long.MIN_VALUE,15000);assertFalse(l.deadlineCurrent(t,Long.MAX_VALUE));assertEquals(-1,l.elapsedMillis(t,Long.MAX_VALUE));}
    @Test void noOperationCannotCompleteActiveLease(){var l=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),100,15000);l.commit(t);assertFalse(l.completeRetained(t,null));assertEquals(FarmMaintenanceLease.State.HELPER_ACTIVE,l.state());}
    @Test void pureReadyResumeDoesNotBecomeRetainedNativeClosure(){var l=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),100,15000);l.commit(t);l.beginRestore(t);l.beginReturn(t);l.ready(t);l.resume(t);assertFalse(l.completedRetainedDeadlineCurrent(t,null,101));}
    @Test void foreignTokenCannotCompleteOrCheckRetainedClosure(){var l=new FarmMaintenanceLease();var other=new FarmMaintenanceLease();var t=l.prepare(new Object(),new Object(),100,15000);var foreign=other.prepare(new Object(),new Object(),100,15000);l.commit(t);assertFalse(l.completeRetained(foreign,null));assertFalse(l.completedRetainedDeadlineCurrent(foreign,null,101));assertTrue(l.deadlineCurrent(t,101));}
}
